          <pre>import os
from dotenv import load_dotenv
load_dotenv()

import neatlogs
neatlogs.init(
    api_key=os.environ["NEATLOGS_API_KEY"],
    workflow_name="outofoffice",
    instrumentations=[<span class="ok">"langgraph", "langchain", "anthropic"</span>],
    tags={"env": "hackathon", "section": "1"},
)</pre>
