          <text class="dmono-sm" x="380" y="139" text-anchor="middle">nothing enters git until you commit</text>

          <g color="var(--ink-2)">
            <line class="darr" x1="380" y1="150" x2="380" y2="180" marker-end="url(#arw)"></line>
          </g>
          <text class="dmono-sm" x="392" y="169">git commit fires the post-commit hook</text>

