          <text class="dtext" x="30" y="70">Agent run in production</text>
          <text class="dmono-sm" x="30" y="88">@span(kind="WORKFLOW")</text>

          <rect class="b-neat" x="325" y="46" width="250" height="56"></rect>
          <text class="dtext t-neat" x="341" y="70">Span tree → ingest</text>
          <text class="dmono-sm t-neat" x="341" y="88">auto-instrumentation, in-process</text>

          <rect class="b-alert" x="636" y="46" width="250" height="56"></rect>
