from app.state import RoveState


def score(candidate: dict, tag_weights: dict) -> float:
    """Sum of the user's weights over the candidate's tags. Arithmetic, not a model call."""
    return round(sum(tag_weights.get(tag, 0.0) for tag in candidate.get("tags", [])), 3)


def taste(state: RoveState) -> dict:
    tag_weights = state.get("taste", {}).get("tags", {})
    scored = [{**c, "score": score(c, tag_weights)} for c in state.get("candidates", [])]
    # sorted() is stable, so ties keep scout's order
    return {"ranked": sorted(scored, key=lambda c: c["score"], reverse=True)}

from app.state import RoveState

# Which budget category a candidate's cost is charged to.
CATEGORY = {"place": "activities", "event": "activities", "shop": "shopping"}


def remaining(budget: dict, category: str) -> float | None:
    """Money left in a category, or None when no allocation was set for it."""
    alloc = budget.get("alloc", {})
    if category not in alloc:
        return None
    return alloc[category] - budget.get("spent", {}).get(category, 0)


def budget(state: RoveState) -> dict:
    b = state.get("budget", {})
    warnings = list(state.get("warnings", []))

    for category, allocated in b.get("alloc", {}).items():
        spent = b.get("spent", {}).get(category, 0)
        if spent > allocated:
            warnings.append(f"overspent on {category}: ₹{spent:g} of ₹{allocated:g}")

    kept = []
    for c in state.get("ranked", []):
        left = remaining(b, CATEGORY.get(c.get("kind"), "activities"))
        if left is None or c.get("cost_inr", 0) <= left:
            kept.append(c)
    return {"ranked": kept, "warnings": warnings}

from app.state import RoveState

# Fabrics that are wrong for an activity. Linen on the Dudhsagar trek is the demo case.
UNSUITABLE = {
    "trek": {"linen", "silk", "wool"},
    "beach": {"silk", "wool"},
}
# Fabric to reach for first when it is packed.
PREFERRED = {
    "trek": "quick-dry",
    "sunset": "linen",
}


def pick_outfit(activity: str, wardrobe: list) -> dict | None:
    suitable = [w for w in wardrobe if w["fabric"] not in UNSUITABLE.get(activity, set())]
    for w in suitable:
        if w["fabric"] == PREFERRED.get(activity):
            return w
    return suitable[0] if suitable else None


def wardrobe(state: RoveState) -> dict:
    packed = state.get("wardrobe", [])
    warnings = list(state.get("warnings", []))
    if not packed:
        # nothing recorded as packed: no constraint to apply
        return {"ranked": state.get("ranked", []), "warnings": warnings}

    kept = []
    for c in state.get("ranked", []):
        outfit = pick_outfit(c.get("activity", ""), packed)
        if outfit is None:
            warnings.append(f"nothing packed suits {c['name']} ({c.get('activity')})")
            continue
        kept.append({**c, "outfit": outfit["id"]})
    return {"ranked": kept, "warnings": warnings}

